    "id": "mevr-c-e-m-goos-emmeloord-acupunctuur-emmeloord-carine-goos",
    "name": "Mevr. C.E.M. Goos",
    "practiceName": "Acupunctuur Emmeloord Carine Goos",
    "specialty": "Acupuncture",
    "specializationDetail": "Acupuncture, Balance Method, Cupping, Pediatric Acupuncture, Moxa, Chinese Herbs, Dry Needling",
    "clinic": "Emmeloord",
    "province": "Flevoland",
