    "phone": "06 30621426",
    "email": "ilse.tomassen@upcmail.nl",
    "website": "www.acupunctuur-arnhem-oosterbeek.nl",
    "association": "Nederlandse Vereniging voor Acupunctuur",
    "source": "acupunctuur.nl",
